contracts/AgreementSigner.sol.content:
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/Ownable.sol";

/**
 * @title  AgreementSigner
 * @notice On-chain digital deed signature for real-estate property sales.
 *
 * Flow:
 *   1. Backend (or seller) calls createAgreement() with the keccak256 hash of
 *      the PDF agreement uploaded to IPFS, linking it to a tokenId, seller,
 *      and buyer.
 *   2. Seller calls signAgreement(agreementId)  → their wallet confirms.
 *   3. Buyer  calls signAgreement(agreementId)  → their wallet confirms.
 *   4. Once both have signed, AgreementCompleted is emitted — the backend
 *      listens for this event to unlock the escrow release step.
 *
 * Document integrity:
 *   - Frontend can call verifyDocumentHash() before prompting a signature to
 *     confirm the IPFS document matches the on-chain hash.
 */
contract AgreementSigner is Ownable {

    // ─────────────────────────────────────────────────────────────────────────
    //  Structs
    // ─────────────────────────────────────────────────────────────────────────

    struct Agreement {
        uint256 agreementId;
        uint256 tokenId;            // property NFT this agreement covers
        address seller;
        address buyer;
        bytes32 documentHash;       // keccak256 of the PDF (stored on IPFS)
        string  ipfsUri;            // IPFS URI of the agreement PDF
        bool    sellerSigned;
        bool    buyerSigned;
        uint256 sellerSignedAt;     // unix timestamp of seller signature (0 if unsigned)
        uint256 buyerSignedAt;      // unix timestamp of buyer  signature (0 if unsigned)
        uint256 createdAt;
    }

    // ─────────────────────────────────────────────────────────────────────────
    //  State
    // ─────────────────────────────────────────────────────────────────────────

    uint256 private _nextAgreementId = 1;

    /// agreementId → Agreement
    mapping(uint256 => Agreement) public agreements;

    /// tokenId → latest agreementId (convenience lookup)
    mapping(uint256 => uint256) public tokenToAgreement;

    // ─────────────────────────────────────────────────────────────────────────
    //  Events
    // ─────────────────────────────────────────────────────────────────────────

    event AgreementCreated(
        uint256 indexed agreementId,
        uint256 indexed tokenId,
        address indexed seller,
        address buyer,
        bytes32 documentHash,
        string  ipfsUri
    );

    event AgreementSigned(
        uint256 indexed agreementId,
        uint256 indexed tokenId,
        address indexed signer,
        bool    isSellerSignature
    );

    event AgreementCompleted(
        uint256 indexed agreementId,
        uint256 indexed tokenId,
        address seller,
        address buyer
    );

    // ─────────────────────────────────────────────────────────────────────────
    //  Constructor
    // ─────────────────────────────────────────────────────────────────────────

    constructor() Ownable() {}

    // ─────────────────────────────────────────────────────────────────────────
    //  Core: Create Agreement
    // ─────────────────────────────────────────────────────────────────────────

    /**
     * @notice Create a new digital sale agreement tied to a property token.
     * @dev    Called by the backend (platform wallet) or the seller after the
     *         PDF has been uploaded to IPFS.  Only one active (unsigned) agreement
     *         per tokenId is allowed at a time.
     *
     * @param  tokenId       The property NFT this agreement covers.
     * @param  seller        Seller's wallet address.
     * @param  buyer         Buyer's wallet address.
     * @param  documentHash  keccak256 hash of the PDF agreement file.
     * @param  ipfsUri       IPFS URI where the agreement PDF is stored.
     * @return agreementId   The newly created agreement ID.
     */
    function createAgreement(
        uint256 tokenId,
        address seller,
        address buyer,
        bytes32 documentHash,
        string  calldata ipfsUri
    )
        external
        returns (uint256 agreementId)
    {
        require(seller       != address(0),  "AgreementSigner: invalid seller");
        require(buyer        != address(0),  "AgreementSigner: invalid buyer");
        require(seller       != buyer,       "AgreementSigner: seller and buyer must differ");
        require(documentHash != bytes32(0),  "AgreementSigner: invalid document hash");
        require(bytes(ipfsUri).length > 0,   "AgreementSigner: IPFS URI required");

        // Ensure no unsigned agreement already open for this token
        uint256 existing = tokenToAgreement[tokenId];
        if (existing != 0) {
            Agreement storage prev = agreements[existing];
            require(
                prev.sellerSigned && prev.buyerSigned,
                "AgreementSigner: prior agreement for this token is not yet complete"
            );
        }

        agreementId = _nextAgreementId++;

        agreements[agreementId] = Agreement({
            agreementId:    agreementId,
            tokenId:        tokenId,
            seller:         seller,
            buyer:          buyer,
            documentHash:   documentHash,
            ipfsUri:        ipfsUri,
            sellerSigned:   false,
            buyerSigned:    false,
            sellerSignedAt: 0,
            buyerSignedAt:  0,
            createdAt:      block.timestamp
        });

        tokenToAgreement[tokenId] = agreementId;

        emit AgreementCreated(agreementId, tokenId, seller, buyer, documentHash, ipfsUri);
    }

    // ─────────────────────────────────────────────────────────────────────────
    //  Core: Sign Agreement
    // ─────────────────────────────────────────────────────────────────────────

    /**
     * @notice Seller or buyer signs the agreement.
     *         Each party must sign in a separate transaction (separate wallet confirmation).
     *         Emits AgreementCompleted once both parties have signed.
     *
     * @param  agreementId  The agreement to sign.
     */
    function signAgreement(uint256 agreementId) external {
        Agreement storage a = agreements[agreementId];

        require(a.agreementId != 0,                          "AgreementSigner: agreement does not exist");
        require(!(a.sellerSigned && a.buyerSigned),          "AgreementSigner: agreement already complete");
        require(
            msg.sender == a.seller || msg.sender == a.buyer,
            "AgreementSigner: caller is not a party to this agreement"
        );

        bool isSellerSignature;

        if (msg.sender == a.seller) {
            require(!a.sellerSigned, "AgreementSigner: seller has already signed");
            a.sellerSigned   = true;
            a.sellerSignedAt = block.timestamp;
            isSellerSignature = true;
        } else {
            require(!a.buyerSigned, "AgreementSigner: buyer has already signed");
            a.buyerSigned   = true;
            a.buyerSignedAt = block.timestamp;
            isSellerSignature = false;
        }

        emit AgreementSigned(agreementId, a.tokenId, msg.sender, isSellerSignature);

        // If both parties have now signed, emit the completion event
        if (a.sellerSigned && a.buyerSigned) {
            emit AgreementCompleted(agreementId, a.tokenId, a.seller, a.buyer);
        }
    }

    // ─────────────────────────────────────────────────────────────────────────
    //  Views
    // ─────────────────────────────────────────────────────────────────────────

    /**
     * @notice Verify that a given document hash matches the hash stored on-chain.
     *         Frontend calls this before prompting the user to sign, ensuring the
     *         IPFS document has not been tampered with.
     *
     * @param  agreementId    The agreement to check.
     * @param  documentHash   keccak256 hash of the document the frontend fetched from IPFS.
     * @return matches        true if the hashes match.
     */
    function verifyDocumentHash(uint256 agreementId, bytes32 documentHash)
        external
        view
        returns (bool matches)
    {
        return agreements[agreementId].documentHash == documentHash;
    }

    /**
     * @notice Returns the full Agreement struct for a given ID.
     */
    function getAgreement(uint256 agreementId)
        external
        view
        returns (Agreement memory)
    {
        return agreements[agreementId];
    }

    /**
     * @notice Returns the latest agreement ID for a given tokenId.
     *         Returns 0 if no agreement exists for the token.
     */
    function getAgreementByToken(uint256 tokenId)
        external
        view
        returns (uint256 agreementId)
    {
        return tokenToAgreement[tokenId];
    }

    /**
     * @notice Returns whether both parties have signed a given agreement.
     */
    function isComplete(uint256 agreementId) external view returns (bool) {
        Agreement storage a = agreements[agreementId];
        return a.sellerSigned && a.buyerSigned;
    }

    /**
     * @notice Returns individual signing status for both parties.
     */
    function getSigningStatus(uint256 agreementId)
        external
        view
        returns (
            bool sellerSigned,
            bool buyerSigned,
            uint256 sellerSignedAt,
            uint256 buyerSignedAt
        )
    {
        Agreement storage a = agreements[agreementId];
        return (a.sellerSigned, a.buyerSigned, a.sellerSignedAt, a.buyerSignedAt);
    }
}

contracts/Auction.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC721/IERC721.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

/**
 * @title  IPropertyNFT
 * @notice Minimal interface to check verification status on PropertyNFT.sol
 */
interface IPropertyNFT {
    function isVerified(uint256 tokenId) external view returns (bool);
    function ownerOf(uint256 tokenId) external view returns (address);
}

/**
 * @title  Auction
 * @notice Timed English auction with:
 *           • Pull-over-push withdrawal for outbid users (reentrancy safe)
 *           • Anti-sniping: last-5-minute bids extend the auction by 5 min
 *           • Automatic winner resolution on finalize
 *           • No-bid path: NFT returned to seller
 */
contract Auction is ReentrancyGuard, Ownable {

    // ─────────────────────────────────────────────────────────────────────────
    //  Constants
    // ─────────────────────────────────────────────────────────────────────────

    uint256 public constant ANTI_SNIPE_WINDOW     = 5 minutes;
    uint256 public constant ANTI_SNIPE_EXTENSION  = 5 minutes;

    // ─────────────────────────────────────────────────────────────────────────
    //  Structs
    // ─────────────────────────────────────────────────────────────────────────

    struct AuctionData {
        uint256 auctionId;
        uint256 tokenId;
        address seller;
        uint256 startingPrice;       // minimum first bid (wei)
        uint256 highestBid;          // current highest bid (wei)
        address highestBidder;       // address(0) if no bids yet
        uint256 endTime;             // unix timestamp
        bool    finalized;
    }

    // ─────────────────────────────────────────────────────────────────────────
    //  State
    // ─────────────────────────────────────────────────────────────────────────

    IPropertyNFT public propertyNFT;

    uint256 private _nextAuctionId = 1;

    /// auctionId → AuctionData
    mapping(uint256 => AuctionData) public auctions;

    /// auctionId → bidder → pending ETH to withdraw (pull pattern)
    mapping(uint256 => mapping(address => uint256)) public pendingReturns;

    /// ordered list of all auction IDs
    uint256[] private _allAuctionIds;

    // ─────────────────────────────────────────────────────────────────────────
    //  Events
    // ─────────────────────────────────────────────────────────────────────────

    event AuctionCreated(
        uint256 indexed auctionId,
        uint256 indexed tokenId,
        address indexed seller,
        uint256 startingPrice,
        uint256 endTime
    );

    event BidPlaced(
        uint256 indexed auctionId,
        uint256 indexed tokenId,
        address indexed bidder,
        uint256 amount,
        uint256 newEndTime      // may have been extended
    );

    event BidWithdrawn(
        uint256 indexed auctionId,
        address indexed bidder,
        uint256 amount
    );

    event AuctionEnded(
        uint256 indexed auctionId,
        uint256 indexed tokenId,
        address winner,          // address(0) if no bids
        uint256 finalBid
    );

    // ─────────────────────────────────────────────────────────────────────────
    //  Constructor
    // ─────────────────────────────────────────────────────────────────────────

    constructor(address _propertyNFT) Ownable() {
        require(_propertyNFT != address(0), "Auction: zero address");
        propertyNFT = IPropertyNFT(_propertyNFT);
    }

    // ─────────────────────────────────────────────────────────────────────────
    //  Core: Create Auction
    // ─────────────────────────────────────────────────────────────────────────

    /**
     * @notice Create a timed auction for a verified property NFT.
     * @dev    Caller must approve this contract before calling.
     *         NFT is transferred into contract custody immediately.
     * @param  tokenId        The ERC-721 token to auction.
     * @param  startingPrice  Minimum opening bid in wei.
     * @param  duration       Auction length in seconds.
     * @return auctionId      The newly created auction ID.
     */
    function createAuction(
        uint256 tokenId,
        uint256 startingPrice,
        uint256 duration
    )
        external
        nonReentrant
        returns (uint256 auctionId)
    {
        require(startingPrice > 0,                            "Auction: starting price must be > 0");
        require(duration > 0,                                 "Auction: duration must be > 0");
        require(propertyNFT.isVerified(tokenId),             "Auction: property not verified");
        require(propertyNFT.ownerOf(tokenId) == msg.sender,  "Auction: not token owner");

        // Transfer NFT to contract
        IERC721(address(propertyNFT)).transferFrom(msg.sender, address(this), tokenId);

        auctionId = _nextAuctionId++;
        uint256 endTime = block.timestamp + duration;

        auctions[auctionId] = AuctionData({
            auctionId:     auctionId,
            tokenId:       tokenId,
            seller:        msg.sender,
            startingPrice: startingPrice,
            highestBid:    0,
            highestBidder: address(0),
            endTime:       endTime,
            finalized:     false
        });

        _allAuctionIds.push(auctionId);

        emit AuctionCreated(auctionId, tokenId, msg.sender, startingPrice, endTime);
    }

    // ─────────────────────────────────────────────────────────────────────────
    //  Core: Place Bid
    // ─────────────────────────────────────────────────────────────────────────

    /**
     * @notice Place a bid on an active auction.
     * @dev    Pull-over-push: the previous highest bidder's ETH is stored in
     *         `pendingReturns` — they must call withdraw() to retrieve it.
     *
     *         Anti-sniping: if a bid arrives within the last ANTI_SNIPE_WINDOW
     *         seconds, endTime is extended by ANTI_SNIPE_EXTENSION.
     *
     * @param  auctionId  ID of the active auction.
     */
    function placeBid(uint256 auctionId) external payable nonReentrant {
        AuctionData storage a = auctions[auctionId];

        require(!a.finalized,                  "Auction: already finalized");
        require(block.timestamp < a.endTime,   "Auction: auction has ended");
        require(a.seller != address(0),        "Auction: does not exist");
        require(msg.sender != a.seller,        "Auction: seller cannot bid");

        // Bid must exceed current highest bid (or startingPrice if first bid)
        uint256 floor = a.highestBid > 0 ? a.highestBid : a.startingPrice;
        require(msg.value > floor, "Auction: bid too low");

        // Queue previous highest bidder's ETH for withdrawal
        if (a.highestBidder != address(0)) {
            pendingReturns[auctionId][a.highestBidder] += a.highestBid;
        }

        // Record new highest bid
        a.highestBid    = msg.value;
        a.highestBidder = msg.sender;

        // ── Anti-sniping extension ─────────────────────────────────────────
        if (a.endTime - block.timestamp <= ANTI_SNIPE_WINDOW) {
            a.endTime += ANTI_SNIPE_EXTENSION;
        }

        emit BidPlaced(auctionId, a.tokenId, msg.sender, msg.value, a.endTime);
    }

    // ─────────────────────────────────────────────────────────────────────────
    //  Core: Withdraw (outbid funds)
    // ─────────────────────────────────────────────────────────────────────────

    /**
     * @notice Outbid users call this to reclaim their ETH.
     *         Pull-over-push pattern prevents reentrancy and DoS attacks.
     * @param  auctionId  The auction from which to withdraw pending funds.
     */
    function withdraw(uint256 auctionId) external nonReentrant {
        uint256 amount = pendingReturns[auctionId][msg.sender];
        require(amount > 0, "Auction: nothing to withdraw");

        // Zero before transfer (CEI)
        pendingReturns[auctionId][msg.sender] = 0;

        (bool ok, ) = msg.sender.call{value: amount}("");
        require(ok, "Auction: ETH transfer failed");

        emit BidWithdrawn(auctionId, msg.sender, amount);
    }

    // ─────────────────────────────────────────────────────────────────────────
    //  Core: Finalize Auction
    // ─────────────────────────────────────────────────────────────────────────

    /**
     * @notice Finalize an ended auction.  Anyone may call this after endTime.
     *
     *         • If bids exist:  NFT → winner, ETH → seller.
     *         • If no bids:     NFT → seller.
     *
     * @param  auctionId  ID of the ended auction.
     */
    function finalizeAuction(uint256 auctionId) external nonReentrant {
        AuctionData storage a = auctions[auctionId];

        require(a.seller != address(0),        "Auction: does not exist");
        require(!a.finalized,                  "Auction: already finalized");
        require(block.timestamp >= a.endTime,  "Auction: not yet ended");

        a.finalized = true;

        if (a.highestBidder != address(0)) {
            // ── Winner path ───────────────────────────────────────────────
            IERC721(address(propertyNFT)).safeTransferFrom(
                address(this), a.highestBidder, a.tokenId
            );

            (bool ok, ) = a.seller.call{value: a.highestBid}("");
            require(ok, "Auction: seller payment failed");

            emit AuctionEnded(auctionId, a.tokenId, a.highestBidder, a.highestBid);
        } else {
            // ── No bids: return NFT to seller ─────────────────────────────
            IERC721(address(propertyNFT)).safeTransferFrom(
                address(this), a.seller, a.tokenId
            );

            emit AuctionEnded(auctionId, a.tokenId, address(0), 0);
        }
    }

    // ─────────────────────────────────────────────────────────────────────────
    //  Views
    // ─────────────────────────────────────────────────────────────────────────

    /**
     * @notice Returns full AuctionData for a given auction ID.
     */
    function getAuction(uint256 auctionId)
        external
        view
        returns (AuctionData memory)
    {
        return auctions[auctionId];
    }

    /**
     * @notice Returns all auction IDs whose endTime is in the future
     *         and that have not yet been finalized.
     */
    function getActiveAuctionIds()
        external
        view
        returns (uint256[] memory activeIds)
    {
        uint256 total = _allAuctionIds.length;
        uint256 count = 0;

        for (uint256 i = 0; i < total; i++) {
            AuctionData storage a = auctions[_allAuctionIds[i]];
            if (!a.finalized && block.timestamp < a.endTime) count++;
        }

        activeIds = new uint256[](count);
        uint256 idx = 0;
        for (uint256 i = 0; i < total; i++) {
            uint256 id = _allAuctionIds[i];
            AuctionData storage a = auctions[id];
            if (!a.finalized && block.timestamp < a.endTime) {
                activeIds[idx++] = id;
            }
        }
    }

    /**
     * @notice Pending ETH a specific bidder can withdraw from an auction.
     * @param  auctionId  The auction ID.
     * @param  bidder     The bidder's address.
     * @return            Amount in wei claimable via withdraw().
     */
    function getPendingReturn(uint256 auctionId, address bidder)
        external
        view
        returns (uint256)
    {
        return pendingReturns[auctionId][bidder];
    }

    // ─────────────────────────────────────────────────────────────────────────
    //  ERC-721 Receiver
    // ─────────────────────────────────────────────────────────────────────────

    function onERC721Received(
        address,
        address,
        uint256,
        bytes calldata
    ) external pure returns (bytes4) {
        return this.onERC721Received.selector;
    }
}

contracts/Escrow.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

/**
 * @title  Escrow
 * @notice Holds ETH securely during a real-estate property sale.
 *
 * State machine per deal:
 *
 *   AWAITING_PAYMENT
 *        │
 *        ▼  (buyer deposits ETH via createDeal)
 *   AWAITING_DELIVERY ──── buyer confirms ──▶ COMPLETE
 *        │
 *        ├── either party raises dispute ──▶ DISPUTED
 *        │                                      │
 *        │                              arbiter resolves
 *        │                               ┌──────┴──────┐
 *        │                               ▼             ▼
 *        │                           COMPLETE       REFUNDED
 *        │
 *        └── timeout exceeded (seller didn't deliver) ──▶ REFUNDED
 *             (buyer calls claimRefund)
 */
contract Escrow is ReentrancyGuard, Ownable {

    // ─────────────────────────────────────────────────────────────────────────
    //  Enums & Structs
    // ─────────────────────────────────────────────────────────────────────────

    enum State {
        AWAITING_PAYMENT,   // 0  — deal created but no funds yet (unused in flow; deal starts funded)
        AWAITING_DELIVERY,  // 1  — funds locked, waiting for seller to deliver
        COMPLETE,           // 2  — buyer confirmed; funds released to seller
        DISPUTED,           // 3  — either party raised a dispute
        REFUNDED            // 4  — buyer received refund
    }

    struct Deal {
        uint256 dealId;
        uint256 tokenId;        // property NFT token ID
        address buyer;
        address seller;
        address arbiter;        // admin / platform arbiter
        uint256 amount;         // ETH locked (wei)
        State   state;
        uint256 deliveryDeadline; // unix timestamp: seller must deliver by this time
        uint256 createdAt;
    }

    // ─────────────────────────────────────────────────────────────────────────
    //  State
    // ─────────────────────────────────────────────────────────────────────────

    /// Default delivery window (configurable by owner)
    uint256 public deliveryWindowDays = 30 days;

    uint256 private _nextDealId = 1;

    /// dealId → Deal
    mapping(uint256 => Deal) public deals;

    /// dealId → history of state-change timestamps (for audit trail)
    mapping(uint256 => uint256[]) public stateHistory; // parallel to StateLog events

    // ─────────────────────────────────────────────────────────────────────────
    //  Events
    // ─────────────────────────────────────────────────────────────────────────

    event DealCreated(
        uint256 indexed dealId,
        uint256 indexed tokenId,
        address indexed buyer,
        address seller,
        address arbiter,
        uint256 amount,
        uint256 deliveryDeadline
    );

    event FundsDeposited(
        uint256 indexed dealId,
        address indexed buyer,
        uint256 amount
    );

    event DealCompleted(
        uint256 indexed dealId,
        uint256 indexed tokenId,
        address indexed seller,
        uint256 amount
    );

    event DisputeRaised(
        uint256 indexed dealId,
        address indexed raisedBy
    );

    event DealRefunded(
        uint256 indexed dealId,
        uint256 indexed tokenId,
        address indexed buyer,
        uint256 amount
    );

    event DisputeResolved(
        uint256 indexed dealId,
        address indexed resolvedBy,
        bool    releasedToSeller   // true = seller paid, false = buyer refunded
    );

    // ─────────────────────────────────────────────────────────────────────────
    //  Constructor
    // ─────────────────────────────────────────────────────────────────────────

    constructor() Ownable() {}

    // ─────────────────────────────────────────────────────────────────────────
    //  Modifiers
    // ─────────────────────────────────────────────────────────────────────────

    modifier onlyBuyer(uint256 dealId) {
        require(deals[dealId].buyer == msg.sender, "Escrow: caller is not the buyer");
        _;
    }

    modifier onlyParticipant(uint256 dealId) {
        Deal storage d = deals[dealId];
        require(
            msg.sender == d.buyer || msg.sender == d.seller,
            "Escrow: caller is not a deal participant"
        );
        _;
    }

    modifier onlyArbiter(uint256 dealId) {
        require(deals[dealId].arbiter == msg.sender, "Escrow: caller is not the arbiter");
        _;
    }

    modifier inState(uint256 dealId, State expected) {
        require(deals[dealId].state == expected, "Escrow: invalid state for this action");
        _;
    }

    // ─────────────────────────────────────────────────────────────────────────
    //  Core: Create Deal
    // ─────────────────────────────────────────────────────────────────────────

    /**
     * @notice Buyer creates and funds an escrow deal in a single transaction.
     * @dev    msg.value must equal the agreed sale price exactly.
     *         Deal moves straight to AWAITING_DELIVERY on creation.
     *
     * @param  tokenId   The property NFT token ID this deal covers.
     * @param  seller    The seller's wallet address.
     * @param  arbiter   The arbiter (admin) address for dispute resolution.
     * @return dealId    The newly created deal ID.
     */
    function createDeal(
        uint256 tokenId,
        address seller,
        address arbiter
    )
        external
        payable
        nonReentrant
        returns (uint256 dealId)
    {
        require(msg.value > 0,            "Escrow: must deposit ETH");
        require(seller  != address(0),    "Escrow: invalid seller address");
        require(arbiter != address(0),    "Escrow: invalid arbiter address");
        require(seller  != msg.sender,    "Escrow: buyer and seller cannot be the same");
        require(arbiter != msg.sender,    "Escrow: buyer cannot be arbiter");
        require(arbiter != seller,        "Escrow: seller cannot be arbiter");

        dealId = _nextDealId++;

        uint256 deadline = block.timestamp + deliveryWindowDays;

        deals[dealId] = Deal({
            dealId:           dealId,
            tokenId:          tokenId,
            buyer:            msg.sender,
            seller:           seller,
            arbiter:          arbiter,
            amount:           msg.value,
            state:            State.AWAITING_DELIVERY,
            deliveryDeadline: deadline,
            createdAt:        block.timestamp
        });

        _logStateChange(dealId);

        emit DealCreated(dealId, tokenId, msg.sender, seller, arbiter, msg.value, deadline);
        emit FundsDeposited(dealId, msg.sender, msg.value);
    }

    // ─────────────────────────────────────────────────────────────────────────
    //  Core: Confirm Delivery (Buyer)
    // ─────────────────────────────────────────────────────────────────────────

    /**
     * @notice Buyer confirms that delivery/transfer has occurred.
     *         Releases locked ETH to the seller and marks deal COMPLETE.
     * @param  dealId  The deal to confirm.
     */
    function confirmDelivery(uint256 dealId)
        external
        nonReentrant
        onlyBuyer(dealId)
        inState(dealId, State.AWAITING_DELIVERY)
    {
        Deal storage d = deals[dealId];

        d.state = State.COMPLETE;
        _logStateChange(dealId);

        uint256 payout = d.amount;
        d.amount = 0;

        (bool ok, ) = d.seller.call{value: payout}("");
        require(ok, "Escrow: seller transfer failed");

        emit DealCompleted(dealId, d.tokenId, d.seller, payout);
    }

    // ─────────────────────────────────────────────────────────────────────────
    //  Core: Raise Dispute
    // ─────────────────────────────────────────────────────────────────────────

    /**
     * @notice Either party (buyer or seller) can raise a dispute.
     *         Locks funds until the arbiter resolves.
     * @param  dealId  The deal to dispute.
     */
    function raiseDispute(uint256 dealId)
        external
        onlyParticipant(dealId)
        inState(dealId, State.AWAITING_DELIVERY)
    {
        deals[dealId].state = State.DISPUTED;
        _logStateChange(dealId);

        emit DisputeRaised(dealId, msg.sender);
    }

    // ─────────────────────────────────────────────────────────────────────────
    //  Core: Resolve Dispute (Arbiter)
    // ─────────────────────────────────────────────────────────────────────────

    /**
     * @notice Arbiter resolves a disputed deal.
     * @param  dealId          The disputed deal.
     * @param  releaseToSeller true  → pay seller (deal COMPLETE)
     *                         false → refund buyer (deal REFUNDED)
     */
    function resolveDispute(uint256 dealId, bool releaseToSeller)
        external
        nonReentrant
        onlyArbiter(dealId)
        inState(dealId, State.DISPUTED)
    {
        Deal storage d = deals[dealId];

        uint256 payout = d.amount;
        d.amount = 0;

        if (releaseToSeller) {
            d.state = State.COMPLETE;
            _logStateChange(dealId);

            (bool ok, ) = d.seller.call{value: payout}("");
            require(ok, "Escrow: seller transfer failed");

            emit DealCompleted(dealId, d.tokenId, d.seller, payout);
        } else {
            d.state = State.REFUNDED;
            _logStateChange(dealId);

            (bool ok, ) = d.buyer.call{value: payout}("");
            require(ok, "Escrow: buyer refund failed");

            emit DealRefunded(dealId, d.tokenId, d.buyer, payout);
        }

        emit DisputeResolved(dealId, msg.sender, releaseToSeller);
    }

    // ─────────────────────────────────────────────────────────────────────────
    //  Core: Automatic Refund Timeout (Buyer)
    // ─────────────────────────────────────────────────────────────────────────

    /**
     * @notice If the seller fails to deliver before `deliveryDeadline`,
     *         the buyer can claim an automatic refund without arbiter involvement.
     * @param  dealId  The deal to refund.
     */
    function claimRefund(uint256 dealId)
        external
        nonReentrant
        onlyBuyer(dealId)
        inState(dealId, State.AWAITING_DELIVERY)
    {
        Deal storage d = deals[dealId];
        require(block.timestamp > d.deliveryDeadline, "Escrow: delivery deadline not yet passed");

        d.state = State.REFUNDED;
        _logStateChange(dealId);

        uint256 payout = d.amount;
        d.amount = 0;

        (bool ok, ) = d.buyer.call{value: payout}("");
        require(ok, "Escrow: refund transfer failed");

        emit DealRefunded(dealId, d.tokenId, d.buyer, payout);
    }

    // ─────────────────────────────────────────────────────────────────────────
    //  Views
    // ─────────────────────────────────────────────────────────────────────────

    /**
     * @notice Returns the full Deal struct for a given deal ID.
     */
    function getDeal(uint256 dealId) external view returns (Deal memory) {
        return deals[dealId];
    }

    /**
     * @notice Returns the current state label as a string (for debugging).
     */
    function getDealState(uint256 dealId) external view returns (string memory) {
        State s = deals[dealId].state;
        if (s == State.AWAITING_PAYMENT)  return "AWAITING_PAYMENT";
        if (s == State.AWAITING_DELIVERY) return "AWAITING_DELIVERY";
        if (s == State.COMPLETE)          return "COMPLETE";
        if (s == State.DISPUTED)          return "DISPUTED";
        if (s == State.REFUNDED)          return "REFUNDED";
        return "UNKNOWN";
    }

    /**
     * @notice Returns the audit trail of state-change timestamps for a deal.
     */
    function getStateHistory(uint256 dealId)
        external
        view
        returns (uint256[] memory)
    {
        return stateHistory[dealId];
    }

    // ─────────────────────────────────────────────────────────────────────────
    //  Owner Config
    // ─────────────────────────────────────────────────────────────────────────

    /**
     * @notice Update the default delivery window applied to new deals.
     * @param  windowInDays  Window length in days (stored as seconds internally).
     */
    function setDeliveryWindow(uint256 windowInDays) external onlyOwner {
        require(windowInDays > 0, "Escrow: window must be > 0");
        deliveryWindowDays = windowInDays * 1 days;
    }

    // ─────────────────────────────────────────────────────────────────────────
    //  Internal Helpers
    // ─────────────────────────────────────────────────────────────────────────

    /**
     * @dev Records a timestamp for every state transition — audit trail.
     */
    function _logStateChange(uint256 dealId) internal {
        stateHistory[dealId].push(block.timestamp);
    }
}

contracts/Marketplace.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC721/IERC721.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

/**
 * @title  IPropertyNFT
 * @notice Minimal interface to check verification status on PropertyNFT.sol
 */
interface IPropertyNFT {
    function isVerified(uint256 tokenId) external view returns (bool);
    function ownerOf(uint256 tokenId) external view returns (address);
}

/**
 * @title  Marketplace
 * @notice Fixed-price listing, buying, cancellation, and price-update for
 *         verified Real-Estate NFTs.  Platform fee is deducted on every sale.
 *
 * Fee defaults (all configurable by owner):
 *   • Platform fee : 2.5 % (250 basis points)
 *   • Fee recipient: contract deployer
 *   • Minimum price: 0.001 ETH
 */
contract Marketplace is ReentrancyGuard, Ownable {

    // ─────────────────────────────────────────────────────────────────────────
    //  Structs
    // ─────────────────────────────────────────────────────────────────────────

    struct Listing {
        uint256 listingId;
        uint256 tokenId;
        address seller;
        uint256 price;      // in wei
        bool    active;
    }

    // ─────────────────────────────────────────────────────────────────────────
    //  State
    // ─────────────────────────────────────────────────────────────────────────

    IPropertyNFT public propertyNFT;

    uint256 public feeBasisPoints = 250;          // 2.5 %
    address public feeRecipient;
    uint256 public minimumPrice   = 0.001 ether;

    uint256 private _nextListingId = 1;

    /// listingId → Listing
    mapping(uint256 => Listing) public listings;

    /// tokenId → active listingId  (0 = not listed)
    mapping(uint256 => uint256) public tokenToActiveListing;

    /// ordered list of all listing IDs ever created (used for pagination)
    uint256[] private _allListingIds;

    // ─────────────────────────────────────────────────────────────────────────
    //  Events
    // ─────────────────────────────────────────────────────────────────────────

    event Listed(
        uint256 indexed listingId,
        uint256 indexed tokenId,
        address indexed seller,
        uint256 price
    );

    event Sold(
        uint256 indexed listingId,
        uint256 indexed tokenId,
        address indexed buyer,
        uint256 price,
        uint256 fee
    );

    event ListingCancelled(
        uint256 indexed listingId,
        uint256 indexed tokenId,
        address indexed seller
    );

    event PriceUpdated(
        uint256 indexed listingId,
        uint256 indexed tokenId,
        uint256 newPrice
    );

    event FeeUpdated(uint256 newBasisPoints);
    event FeeRecipientUpdated(address newRecipient);
    event MinimumPriceUpdated(uint256 newMinimumPrice);

    // ─────────────────────────────────────────────────────────────────────────
    //  Constructor
    // ─────────────────────────────────────────────────────────────────────────

    constructor(address _propertyNFT) Ownable() {
        require(_propertyNFT != address(0), "Marketplace: zero address");
        propertyNFT  = IPropertyNFT(_propertyNFT);
        feeRecipient = msg.sender;
    }

    // ─────────────────────────────────────────────────────────────────────────
    //  Core: List
    // ─────────────────────────────────────────────────────────────────────────

    /**
     * @notice List a verified property for fixed-price sale.
     * @dev    Caller must have called NFT.approve(address(this), tokenId) first.
     *         NFT is transferred into contract custody (escrow).
     * @param  tokenId  The ERC-721 token to list.
     * @param  price    Asking price in wei (must be >= minimumPrice).
     * @return listingId The newly created listing ID.
     */
    function listProperty(uint256 tokenId, uint256 price)
        external
        nonReentrant
        returns (uint256 listingId)
    {
        require(price >= minimumPrice,                        "Marketplace: price too low");
        require(propertyNFT.isVerified(tokenId),             "Marketplace: property not verified");
        require(propertyNFT.ownerOf(tokenId) == msg.sender,  "Marketplace: not token owner");
        require(tokenToActiveListing[tokenId] == 0,          "Marketplace: already listed");

        // Pull NFT into contract custody
        IERC721(address(propertyNFT)).transferFrom(msg.sender, address(this), tokenId);

        listingId = _nextListingId++;

        listings[listingId] = Listing({
            listingId: listingId,
            tokenId:   tokenId,
            seller:    msg.sender,
            price:     price,
            active:    true
        });

        tokenToActiveListing[tokenId] = listingId;
        _allListingIds.push(listingId);

        emit Listed(listingId, tokenId, msg.sender, price);
    }

    // ─────────────────────────────────────────────────────────────────────────
    //  Core: Buy
    // ─────────────────────────────────────────────────────────────────────────

    /**
     * @notice Purchase a listed property.
     * @dev    Buyer must send msg.value >= listing.price.
     *         Platform fee deducted, remainder forwarded to seller atomically.
     *         Excess ETH returned to buyer.
     * @param  listingId  ID of the active listing.
     */
    function buyProperty(uint256 listingId)
        external
        payable
        nonReentrant
    {
        Listing storage listing = listings[listingId];
        require(listing.active,             "Marketplace: listing not active");
        require(msg.value >= listing.price, "Marketplace: insufficient ETH");

        // ── Mark inactive before transfers (CEI pattern) ──────────────────
        listing.active = false;
        tokenToActiveListing[listing.tokenId] = 0;

        uint256 fee        = (listing.price * feeBasisPoints) / 10_000;
        uint256 sellerAmt  = listing.price - fee;
        uint256 excess     = msg.value - listing.price;

        // ── Transfer NFT to buyer ─────────────────────────────────────────
        IERC721(address(propertyNFT)).safeTransferFrom(
            address(this), msg.sender, listing.tokenId
        );

        // ── Disburse ETH ──────────────────────────────────────────────────
        if (fee > 0) {
            (bool feeOk, ) = feeRecipient.call{value: fee}("");
            require(feeOk, "Marketplace: fee transfer failed");
        }

        (bool sellerOk, ) = listing.seller.call{value: sellerAmt}("");
        require(sellerOk, "Marketplace: seller transfer failed");

        // Return any overpayment
        if (excess > 0) {
            (bool excessOk, ) = msg.sender.call{value: excess}("");
            require(excessOk, "Marketplace: refund failed");
        }

        emit Sold(listingId, listing.tokenId, msg.sender, listing.price, fee);
    }

    // ─────────────────────────────────────────────────────────────────────────
    //  Core: Cancel
    // ─────────────────────────────────────────────────────────────────────────

    /**
     * @notice Cancel an active listing.  Only the original seller may cancel.
     *         NFT is returned to the seller.
     * @param  listingId  ID of the listing to cancel.
     */
    function cancelListing(uint256 listingId) external nonReentrant {
        Listing storage listing = listings[listingId];
        require(listing.active,               "Marketplace: listing not active");
        require(listing.seller == msg.sender, "Marketplace: not the seller");

        listing.active = false;
        tokenToActiveListing[listing.tokenId] = 0;

        IERC721(address(propertyNFT)).safeTransferFrom(
            address(this), listing.seller, listing.tokenId
        );

        emit ListingCancelled(listingId, listing.tokenId, msg.sender);
    }

    // ─────────────────────────────────────────────────────────────────────────
    //  Core: Update Price
    // ─────────────────────────────────────────────────────────────────────────

    /**
     * @notice Update the price of an active listing without re-listing.
     * @param  listingId  ID of the active listing.
     * @param  newPrice   New price in wei (must be >= minimumPrice).
     */
    function updatePrice(uint256 listingId, uint256 newPrice) external {
        Listing storage listing = listings[listingId];
        require(listing.active,               "Marketplace: listing not active");
        require(listing.seller == msg.sender, "Marketplace: not the seller");
        require(newPrice >= minimumPrice,     "Marketplace: price too low");

        listing.price = newPrice;

        emit PriceUpdated(listingId, listing.tokenId, newPrice);
    }

    // ─────────────────────────────────────────────────────────────────────────
    //  View: Active Listings
    // ─────────────────────────────────────────────────────────────────────────

    /**
     * @notice Returns an array of all currently active listing IDs.
     *         Designed for frontend pagination — call off-chain.
     * @return activeIds  Array of active listing IDs.
     */
    function getActiveListingIds()
        external
        view
        returns (uint256[] memory activeIds)
    {
        uint256 total  = _allListingIds.length;
        uint256 count  = 0;

        // First pass: count actives
        for (uint256 i = 0; i < total; i++) {
            if (listings[_allListingIds[i]].active) count++;
        }

        activeIds = new uint256[](count);
        uint256 idx = 0;
        for (uint256 i = 0; i < total; i++) {
            uint256 id = _allListingIds[i];
            if (listings[id].active) {
                activeIds[idx++] = id;
            }
        }
    }

    /**
     * @notice Convenience view: return full Listing struct for a given ID.
     */
    function getListing(uint256 listingId)
        external
        view
        returns (Listing memory)
    {
        return listings[listingId];
    }

    // ─────────────────────────────────────────────────────────────────────────
    //  Owner: Fee Configuration
    // ─────────────────────────────────────────────────────────────────────────

    /**
     * @notice Update the platform fee.  Max 10 % (1 000 bp) as a safety cap.
     * @param  newBasisPoints  Fee in basis points (e.g. 250 = 2.5 %).
     */
    function setFeeBasisPoints(uint256 newBasisPoints) external onlyOwner {
        require(newBasisPoints <= 1_000, "Marketplace: fee too high (max 10%)");
        feeBasisPoints = newBasisPoints;
        emit FeeUpdated(newBasisPoints);
    }

    /**
     * @notice Update the fee recipient address.
     * @param  newRecipient  Address that will receive platform fees.
     */
    function setFeeRecipient(address newRecipient) external onlyOwner {
        require(newRecipient != address(0), "Marketplace: zero address");
        feeRecipient = newRecipient;
        emit FeeRecipientUpdated(newRecipient);
    }

    /**
     * @notice Update the minimum listing price.
     * @param  newMin  Minimum price in wei.
     */
    function setMinimumPrice(uint256 newMin) external onlyOwner {
        minimumPrice = newMin;
        emit MinimumPriceUpdated(newMin);
    }

    // ─────────────────────────────────────────────────────────────────────────
    //  ERC-721 Receiver
    // ─────────────────────────────────────────────────────────────────────────

    /**
     * @dev Required so the contract can receive NFTs via safeTransferFrom.
     */
    function onERC721Received(
        address,
        address,
        uint256,
        bytes calldata
    ) external pure returns (bytes4) {
        return this.onERC721Received.selector;
    }
}

contracts/PropertyNFT.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC721/ERC721.sol";
import "@openzeppelin/contracts/token/ERC721/extensions/ERC721URIStorage.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

/**
 * @title  PropertyNFT
 * @notice ERC-721 token representing verified real-estate properties.
 *
 * Each token stores:
 *   • On-chain metadata  : address, area (sqft), valuation (wei), verified flag
 *   • Off-chain metadata : IPFS URI pointing to the full JSON metadata + documents
 *
 * Only the contract owner (platform admin) can:
 *   • Mint new property tokens
 *   • Verify / unverify properties
 *   • Update token URIs
 */
contract PropertyNFT is ERC721, ERC721URIStorage, Ownable {

    // ─────────────────────────────────────────────────────────────────────────
    //  Structs
    // ─────────────────────────────────────────────────────────────────────────

    struct Property {
        uint256 tokenId;
        string  propertyAddress;   // physical address string
        uint256 areaSqft;          // area in square feet
        uint256 valuation;         // appraised value in wei
        bool    verified;          // admin verification flag
        uint256 mintedAt;          // block timestamp
    }

    // ─────────────────────────────────────────────────────────────────────────
    //  State
    // ─────────────────────────────────────────────────────────────────────────

    uint256 private _nextTokenId = 1;

    /// tokenId → Property metadata
    mapping(uint256 => Property) public properties;

    // ─────────────────────────────────────────────────────────────────────────
    //  Events
    // ─────────────────────────────────────────────────────────────────────────

    event PropertyMinted(
        uint256 indexed tokenId,
        address indexed owner,
        string  propertyAddress,
        uint256 areaSqft,
        uint256 valuation
    );

    event PropertyVerified(uint256 indexed tokenId, bool verified);

    event TokenURIUpdated(uint256 indexed tokenId);

    // ─────────────────────────────────────────────────────────────────────────
    //  Constructor
    // ─────────────────────────────────────────────────────────────────────────

    constructor() ERC721("RealEstateNFT", "RENFT") Ownable() {}

    // ─────────────────────────────────────────────────────────────────────────
    //  Core: Mint
    // ─────────────────────────────────────────────────────────────────────────

    /**
     * @notice Mint a new property token to `to`.
     * @dev    Only platform admin (owner) can mint.
     *         Token is unverified by default; admin calls verifyProperty() after KYC.
     *
     * @param  to              Recipient wallet (property owner).
     * @param  propertyAddress Physical address of the property.
     * @param  areaSqft        Area in square feet.
     * @param  valuation       Appraised value in wei.
     * @param  metadataUri     IPFS URI for the full metadata JSON.
     * @return tokenId         The newly minted token ID.
     */
    function mintProperty(
        address to,
        string  calldata propertyAddress,
        uint256 areaSqft,
        uint256 valuation,
        string  calldata metadataUri
    )
        external
        onlyOwner
        returns (uint256 tokenId)
    {
        require(to != address(0),                    "PropertyNFT: mint to zero address");
        require(bytes(propertyAddress).length > 0,   "PropertyNFT: empty address");
        require(areaSqft > 0,                        "PropertyNFT: area must be > 0");
        require(bytes(metadataUri).length > 0,       "PropertyNFT: empty URI");

        tokenId = _nextTokenId++;

        _safeMint(to, tokenId);
        _setTokenURI(tokenId, metadataUri);

        properties[tokenId] = Property({
            tokenId:         tokenId,
            propertyAddress: propertyAddress,
            areaSqft:        areaSqft,
            valuation:       valuation,
            verified:        false,
            mintedAt:        block.timestamp
        });

        emit PropertyMinted(tokenId, to, propertyAddress, areaSqft, valuation);
    }

    // ─────────────────────────────────────────────────────────────────────────
    //  Core: Verify
    // ─────────────────────────────────────────────────────────────────────────

    /**
     * @notice Mark a property as verified (or revoke verification).
     * @dev    Only admin. Verified properties can be listed on Marketplace/Auction.
     * @param  tokenId   The token to verify.
     */
    function verifyProperty(uint256 tokenId) external onlyOwner {
        require(_ownerOf(tokenId) != address(0), "PropertyNFT: token does not exist");
        properties[tokenId].verified = true;
        emit PropertyVerified(tokenId, true);
    }

    /**
     * @notice Revoke verification for a property.
     * @param  tokenId  The token to unverify.
     */
    function unverifyProperty(uint256 tokenId) external onlyOwner {
        require(_ownerOf(tokenId) != address(0), "PropertyNFT: token does not exist");
        properties[tokenId].verified = false;
        emit PropertyVerified(tokenId, false);
    }

    // ─────────────────────────────────────────────────────────────────────────
    //  Core: Update URI
    // ─────────────────────────────────────────────────────────────────────────

    /**
     * @notice Update the IPFS metadata URI for a token.
     * @dev    Only the current token owner may update their own URI.
     * @param  tokenId     The token to update.
     * @param  newUri      New IPFS URI.
     */
    function updateTokenURI(uint256 tokenId, string calldata newUri)
        external
    {
        require(ownerOf(tokenId) == msg.sender, "PropertyNFT: not token owner");
        require(bytes(newUri).length > 0,        "PropertyNFT: empty URI");
        _setTokenURI(tokenId, newUri);
        emit TokenURIUpdated(tokenId);
    }

    // ─────────────────────────────────────────────────────────────────────────
    //  Views
    // ─────────────────────────────────────────────────────────────────────────

    /**
     * @notice Returns true if the given token is verified by the platform admin.
     */
    function isVerified(uint256 tokenId) external view returns (bool) {
        return properties[tokenId].verified;
    }

    /**
     * @notice Returns the full Property struct for a given tokenId.
     */
    function getProperty(uint256 tokenId)
        external
        view
        returns (Property memory)
    {
        require(_ownerOf(tokenId) != address(0), "PropertyNFT: token does not exist");
        return properties[tokenId];
    }

    /**
     * @notice Returns the total number of tokens minted so far.
     */
    function totalMinted() external view returns (uint256) {
        return _nextTokenId - 1;
    }

    // ─────────────────────────────────────────────────────────────────────────
    //  Overrides required by Solidity for multiple inheritance
    // ─────────────────────────────────────────────────────────────────────────

    function tokenURI(uint256 tokenId)
        public
        view
        override(ERC721, ERC721URIStorage)
        returns (string memory)
    {
        return super.tokenURI(tokenId);
    }

    function supportsInterface(bytes4 interfaceId)
        public
        view
        override(ERC721, ERC721URIStorage)
        returns (bool)
    {
        return super.supportsInterface(interfaceId);
    }

    // Required by OZ v4: ERC721URIStorage overrides _burn internally to
    // clear the stored URI, so the derived contract must explicitly resolve
    // which _burn to call when both ERC721 and ERC721URIStorage define it.
    function _burn(uint256 tokenId)
        internal
        override(ERC721, ERC721URIStorage)
    {
        super._burn(tokenId);
    }
}

